def resolve(path, cwd, links):
    """
    Resolve a path to its canonical absolute path, following symlinks.

    Args:
        path: A path string (relative or absolute)
        cwd: Current working directory (canonical absolute path)
        links: Dict mapping canonical absolute paths to symlink targets

    Returns:
        The canonical absolute path, or None on error
    """
    # Start with the working directory or root
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    links_followed = 0
    max_links = 8

    while True:
        # Split remaining path into components
        if not remaining:
            components = []
        else:
            components = remaining.split('/')

        remaining = ''

        for component in components:
            # Skip empty components and '.'
            if component == '' or component == '.':
                continue

            # Handle '..'
            if component == '..':
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                continue

            # Append the component to current path
            if current == '/':
                current = '/' + component
            else:
                current = current + '/' + component

            # Check if current is a symlink
            if current in links:
                links_followed += 1
                if links_followed > max_links:
                    return None

                target = links[current]

                # Determine the remaining path after the symlink
                # We need to continue with the remaining components
                remaining_idx = components.index(component) + 1
                if remaining_idx < len(components):
                    remaining = '/'.join(components[remaining_idx:])

                # Resolve the link target
                if target.startswith('/'):
                    current = '/'
                    remaining = target[1:]
                    if remaining and components[remaining_idx:]:
                        remaining = remaining + '/' + '/'.join(components[remaining_idx:])
                else:
                    # Target is relative to the directory containing the link
                    if current == '/':
                        link_dir = '/'
                    else:
                        link_dir = current.rsplit('/', 1)[0]
                        if link_dir == '':
                            link_dir = '/'

                    if link_dir == '/':
                        remaining = target
                    else:
                        remaining = target

                    if components[remaining_idx:]:
                        remaining = remaining + '/' + '/'.join(components[remaining_idx:])

                    current = link_dir

                # Break to restart the loop with new remaining path
                break
        else:
            # We processed all components without hitting a symlink
            break

    # Process remaining components if any
    if remaining:
        components = remaining.split('/')
        for component in components:
            if component == '' or component == '.':
                continue

            if component == '..':
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                continue

            if current == '/':
                current = '/' + component
            else:
                current = current + '/' + component

            if current in links:
                links_followed += 1
                if links_followed > max_links:
                    return None

                target = links[current]

                # Determine remaining components
                remaining_idx = components.index(component) + 1
                if target.startswith('/'):
                    current = '/'
                    remaining = target[1:]
                else:
                    if current == '/':
                        link_dir = '/'
                    else:
                        link_dir = current.rsplit('/', 1)[0]
                        if link_dir == '':
                            link_dir = '/'
                    current = link_dir
                    remaining = target

                if remaining_idx < len(components):
                    remaining = remaining + '/' + '/'.join(components[remaining_idx:])

                # Restart with new path
                return resolve('/' + remaining if remaining and not remaining.startswith('/') else remaining, current if remaining.startswith('/') else current, links)

    # Remove trailing slash except for root
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

